import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    results = []
    for item in data:
        if isinstance(item, str):
            try:
                item = ast.literal_eval(item)
            except (ValueError, SyntaxError):
                continue
        if isinstance(item, dict):
            results.append(item)
    keys = []
    for d in results:
        keys.extend(d.keys())
    return Counter(keys)
